function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const CONFIG = {
  bankingUrl: 'https://httpbin.org/post',
  invoicesUrl: 'https://httpbin.org/post',
  schedulesUrl: 'https://httpbin.org/post',
  fxUrl: 'https://httpbin.org/post',
  timeoutMs: 20000,
  // Default forecast settings
  defaultHorizonDays: 30,
  baseCurrency: 'USD',
  allowSimulation: true
};

const hook = ref('Webhook - Forecast Request');
const body = (hook.body && typeof hook.body === 'object') ? hook.body : {};
const errors = [];

const requestId = String(body.requestId || body.id || ('CF-' + Date.now())).trim();
const horizonDays = Number(body.horizonDays || body.days || CONFIG.defaultHorizonDays);
const baseCurrency = String(body.baseCurrency || body.currency || CONFIG.baseCurrency).toUpperCase();
const accounts = Array.isArray(body.accounts) ? body.accounts : (body.accountIds || []);
const asOfDate = String(body.asOfDate || new Date().toISOString().slice(0, 10));
const includeFX = body.includeFX !== false;

if (!Number.isFinite(horizonDays) || horizonDays < 1 || horizonDays > 365) {
  errors.push('horizonDays must be between 1 and 365');
}
if (!baseCurrency || baseCurrency.length !== 3) {
  errors.push('baseCurrency must be a valid 3-letter ISO code');
}

const valid = errors.length === 0;

let bankingUrl = CONFIG.bankingUrl;
const sim = Number(body.simulateStatus);
if (CONFIG.allowSimulation && Number.isInteger(sim) && sim >= 200 && sim <= 599) {
  bankingUrl = 'https://httpbin.org/status/' + sim;
}

return [{
  json: {
    valid,
    errors,
    config: CONFIG,
    request: {
      requestId,
      horizonDays,
      baseCurrency,
      accounts,
      asOfDate,
      includeFX
    },
    urls: {
      banking: bankingUrl,
      invoices: CONFIG.invoicesUrl,
      schedules: CONFIG.schedulesUrl,
      fx: CONFIG.fxUrl
    },
    raw: {
      banking: null,
      invoices: null,
      schedules: null,
      fx: null
    }
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }

const ctx = ref('Code - Validate & Load Sources');
const bankRes = ref('HTTP Request - Fetch Banking Balances') || {};
const invRes = ref('HTTP Request - Fetch Outstanding Invoices') || {};
const schRes = ref('HTTP Request - Fetch Payment Schedules') || {};
const fxRes = ref('HTTP Request - Enrich / FX Rates') || {};

function statusOf(res) {
  return Number(res.statusCode) || 0;
}

const bankOk = statusOf(bankRes) >= 200 && statusOf(bankRes) < 300;
const invOk = statusOf(invRes) >= 200 && statusOf(invRes) < 300;
const schOk = statusOf(schRes) >= 200 && statusOf(schRes) < 300;
const fxOk = statusOf(fxRes) >= 200 && statusOf(fxRes) < 300;

// Simulated / placeholder data extraction (in real use parse actual API bodies)
const openingBalance = 125000; // would come from banking response
const expectedInflows = [
  { dateOffset: 3, amount: 18500, source: 'invoice_collection' },
  { dateOffset: 7, amount: 42000, source: 'invoice_collection' },
  { dateOffset: 14, amount: 9100, source: 'invoice_collection' }
];
const expectedOutflows = [
  { dateOffset: 2, amount: 12500, source: 'ap_payment' },
  { dateOffset: 5, amount: 28000, source: 'payroll' },
  { dateOffset: 10, amount: 8500, source: 'tax' },
  { dateOffset: 15, amount: 6200, source: 'recurring' }
];

// Build daily forecast
const horizon = ctx.request.horizonDays;
const daily = [];
let running = openingBalance;

for (let d = 0; d <= horizon; d++) {
  const dayIn = expectedInflows.filter(i => i.dateOffset === d).reduce((s, i) => s + i.amount, 0);
  const dayOut = expectedOutflows.filter(o => o.dateOffset === d).reduce((s, o) => s + o.amount, 0);
  running = running + dayIn - dayOut;
  daily.push({
    day: d,
    date: new Date(Date.now() + d * 86400000).toISOString().slice(0, 10),
    inflows: dayIn,
    outflows: dayOut,
    net: dayIn - dayOut,
    closingBalance: Math.round(running * 100) / 100
  });
}

const minBalance = Math.min(...daily.map(d => d.closingBalance));
const maxBalance = Math.max(...daily.map(d => d.closingBalance));
const endBalance = daily[daily.length - 1].closingBalance;

const sourcesStatus = {
  banking: { success: bankOk, statusCode: statusOf(bankRes) },
  invoices: { success: invOk, statusCode: statusOf(invRes) },
  schedules: { success: schOk, statusCode: statusOf(schRes) },
  fx: { success: fxOk, statusCode: statusOf(fxRes) }
};

const allSourcesOk = bankOk && invOk && schOk;

const body = {
  requestId: ctx.request.requestId,
  request: ctx.request,
  sourcesStatus,
  summary: {
    openingBalance,
    projectedEndBalance: endBalance,
    minProjectedBalance: minBalance,
    maxProjectedBalance: maxBalance,
    horizonDays: horizon,
    baseCurrency: ctx.request.baseCurrency,
    dataComplete: allSourcesOk
  },
  dailyForecast: daily,
  generatedAt: new Date().toISOString()
};

const httpStatus = allSourcesOk ? 200 : 207; // 207 Multi-Status if partial data

return [{
  json: {
    httpStatus,
    body,
    requestId: ctx.request.requestId
  }
}];
